words = ['hadoop', 'spark', 'hadoop', 'hive', 'spark', 'hadoop']

# ① map 阶段：每个单词 -> (word, 1)
mapped = [(w, 1) for w in words]

# ② reduce 阶段：字典聚合
counts = {}
for word, n in mapped:
    counts[word] = counts.get(word, 0) + n

# ③ 按单词排序输出
for word in sorted(counts):
    print(word, counts[word])

pairs = [('hadoop', 1), ('spark', 1), ('hadoop', 1), ('hive', 1), ('spark', 1), ('hadoop', 1), ('flink', 1)]

# ① 聚合：模拟 reduceByKey，相同 word 的 value 求和
counts = {}
for word, n in pairs:
    counts[word] = counts.get(word, 0) + n

# ② 按 word 字母序输出 'word count'
for word in sorted(counts):
    print(word, counts[word])

sentence = 'hadoop spark hadoop hive'

for word in sentence.split():
