pairs = [('hadoop', 3), ('spark', 2), ('hive', 1), ('flink', 1), ('kafka', 4), ('hbase', 2)]

# ① 分区：模拟 hash 分区，用确定性的 len(word) % 2
partitions = {0: [], 1: []}
for word, count in pairs:
    p = len(word) % 2
    partitions[p].append((word, count))

# ② 分区内按 word 字母序排序
for p in sorted(partitions):
    for word, count in sorted(partitions[p]):
        print(p, word, count)
